    "content": "<h3>🪷 अर्जुन की मछली की आँख का रहस्य</h3><p>जब द्रोणाचार्य ने अपने शिष्यों से पूछा कि पेड़ पर क्या दिखाई दे रहा है, तो किसी को पत्ते, किसी को फल और किसी को शाखाएँ दिखाई दीं। केवल अर्जुन ने कहा—<em>\"मुझे केवल उस चिड़िया की आँख दिखाई दे रही है।\"</em> यही विद्यार्थी जीवन का सर्वोच्च मंत्र है जिसे हम 'Focus' (एकाग्रता) कहते हैं।</p><h3>📖 पढ़ाई में मन कैसे लगाएं?</h3><p>1. <strong>तुलना बंद करें:</strong> किसी सहपाठी के नंबर आपसे अधिक आते हैं, तो ईर्ष्या न करें। श्री कृष्ण कहते हैं कि प्रत्येक आत्मा अद्वितीय है। आपकी प्रतिस्पर्धा केवल आपके कल से है।</p><p>2. <strong>परिणाम का भय त्यागें:</strong> परीक्षा हॉल में जाने से पहले सारा भय प्रभु के चरणों में अर्पित कर दें। जब मन शांत होगा, तभी याद किया हुआ ज्ञान बाहर आएगा।</p><h3>🌟 आज की सीख</h3><p>पढ़ाई को बोझ नहीं, अपनी बुद्धि को तराशने की साधना समझें। <strong>\"सत्यमेव जयते नानृतं।\"</strong></p>"
